package org.beyondlight;

import java.util.*;

/** Repeatable exploratory model fitting over committed local datasets. */
public final class DeterministicResearchEngine {
 private DeterministicResearchEngine() {}
 public static Map<String,Object> run(DataRepository.Dataset d,String xName,String yName){
  List<String> headers;List<List<String>> rows;
  if(d.format().equals("csv")){List<List<String>> t=csv(d.raw());headers=t.get(0);rows=t.subList(1,t.size());}
  else{Map<String,Object> o=Json.map(Json.parse(d.raw()));headers=strings(o.get("variables"));rows=new ArrayList<>();for(Object r:(List<?>)o.get("rows"))rows.add(strings(r));}
  int xi=headers.indexOf(xName),yi=headers.indexOf(yName);if(xi<0||yi<0||xi==yi)throw new IllegalArgumentException("Pilih dua kolom numerik yang berbeda dari dataset.");
  if(rows.size()<6)throw new IllegalArgumentException("Dataset perlu sedikitnya 6 baris agar pembandingan berulang bisa dilakukan.");
  int n=Math.min(rows.size(),5000);double[] x=new double[n],y=new double[n];for(int i=0;i<n;i++){int k=n==rows.size()?i:(int)((long)i*(rows.size()-1)/(n-1));x[i]=Double.parseDouble(rows.get(k).get(xi));y[i]=Double.parseDouble(rows.get(k).get(yi));if(!Double.isFinite(x[i])||!Double.isFinite(y[i]))throw new IllegalArgumentException("Dataset memuat nilai non-finite.");}
  List<Discovery.Candidate> candidates=Discovery.search(join(x),join(y),12);Map<String,String> um=new HashMap<>();for(String p:d.units().split(",")){String[]a=p.trim().split(":",2);if(a.length==2)um.put(a[0].trim(),a[1].trim());}int folds=Math.min(5,n/3);List<Map<String,Object>> models=new ArrayList<>();
  for(var c:candidates){double cv=0,base=0;int tested=0;boolean valid=true;for(int f=0;f<folds;f++){List<Double> tx=new ArrayList<>(),ty=new ArrayList<>();double mean=0;int train=0;for(int i=0;i<n;i++)if(i%folds!=f){tx.add(x[i]);ty.add(y[i]);mean+=y[i];train++;}mean/=train;List<Discovery.Candidate> fitted;try{fitted=Discovery.search(join(tx),join(ty),12);}catch(RuntimeException ex){valid=false;break;}var fit=fitted.stream().filter(q->q.algorithm().equals(c.algorithm())).findFirst().orElse(null);if(fit==null){valid=false;break;}for(int i=0;i<n;i++)if(i%folds==f){double pred=predict(fit,x[i]);cv+=sq(y[i]-pred);base+=sq(y[i]-mean);tested++;}}
   Map<String,Object> units=new LinkedHashMap<>();String xu=um.get(xName),yu=um.get(yName);if(xu!=null&&yu!=null)try{Dimensions.D dx=Dimensions.parse(xu),dy=Dimensions.parse(yu);if(c.algorithm().startsWith("polynomial")){for(int k=0;k<c.parameters().length;k++)units.put("c"+k,dy.minus(dx.scale(k)).toString());}else if(c.algorithm().equals("logarithmic")){units.put("c0",dy.toString());units.put("c1",dy.toString());}else if(c.algorithm().equals("reciprocal")){units.put("c0",dy.toString());units.put("c1",dy.plus(dx).toString());}else if(c.algorithm().equals("exponential")){units.put("amplitude",dy.toString());units.put("exponentCoefficient",dx.scale(-1).toString());}else{units.put("amplitude",dy.minus(dx.scale(c.parameters()[1])).toString());units.put("exponent", "dimensionless");}}catch(Exception ex){units.put("status","inferensi satuan gagal");}else units.put("status","tidak diketahui: satuan sumber tidak tersedia");
   Map<String,Object> m=new LinkedHashMap<>();m.put("algorithm",c.algorithm());m.put("equation",c.expression());m.put("parameters",Arrays.stream(c.parameters()).boxed().toList());m.put("fitRmse",c.rmse());m.put("rSquared",Double.isFinite(c.rSquared())?c.rSquared():null);m.put("coefficientUnitsInferred",units);m.put("crossValidationRmse",valid&&tested>0?Math.sqrt(cv/tested):null);m.put("constantBaselineRmse",valid&&tested>0?Math.sqrt(base/tested):null);m.put("cvBetterThanConstant",valid&&tested>0&&cv<base);m.put("classification",valid&&tested>0&&cv<base?"PATTERN_OUTPERFORMS_CONSTANT_BASELINE_ON_INTERNAL_CV":"NOT_SUPPORTED_AGAINST_CONSTANT_BASELINE");models.add(m);}
  Map<String,Object> out=new LinkedHashMap<>();out.put("id",UUID.randomUUID().toString());out.put("date",java.time.Instant.now().toString());out.put("recordType","DETERMINISTIC_RESEARCH_RUN");out.put("category","research");out.put("title","Eksplorasi dataset: "+d.filename());out.put("model","Model matematis beragam; lipatan validasi deterministik");out.put("inputs",Map.of("datasetId",d.id(),"filename",d.filename(),"x",xName,"y",yName,"rowsAnalyzed",n,"folds",folds,"sampling",rows.size()>n?"sampel merata deterministik":"semua baris"));boolean supported=models.stream().anyMatch(m->Boolean.TRUE.equals(m.get("cvBetterThanConstant")));out.put("result",Map.of("status",models.isEmpty()?"NO_CANDIDATE_MODELS":supported?"PATTERN_SUPPORTED_WITHIN_DATASET":"NO_PATTERN_OUTPERFORMS_BASELINE","models",models));out.put("sources",List.of(Map.of("datasetId",d.id(),"filename",d.filename(),"source",d.source(),"author",d.author(),"year",d.year(),"doi",d.doi(),"conditions",d.conditions(),"uncertainty",d.uncertainty(),"datasetStatus",d.status())));out.put("equations",models.stream().map(m->Map.of("equation",m.get("equation"),"classification",m.get("classification"))).toList());out.put("status",models.isEmpty()?"NO_CANDIDATE_MODELS":supported?"PATTERN_SUPPORTED_WITHIN_DATASET":"NO_PATTERN_OUTPERFORMS_BASELINE");out.put("limitations",List.of("Validasi silang memakai dataset yang sama, bukan data uji independen.","Model empiris tidak menunjukkan sebab-akibat.","Kandidat bukan penemuan hukum fisika atau bukti rekayasa."));return out;
 }
 public static List<Map<String,Object>> discoverAll(List<DataRepository.Dataset> datasets){
  List<Map<String,Object>> runs=new ArrayList<>();int skipped=0;
  outer:for(var d:datasets){List<String> vars=Arrays.asList(d.variables().split(","));if(d.rows()<6){skipped++;continue;}for(String x:vars)for(String y:vars){if(x.equals(y))continue;if(runs.size()>=250)break outer;try{runs.add(run(d,x,y));}catch(RuntimeException ex){Map<String,Object> failed=new LinkedHashMap<>();failed.put("id",UUID.randomUUID().toString());failed.put("date",java.time.Instant.now().toString());failed.put("recordType","DETERMINISTIC_RESEARCH_ATTEMPT");failed.put("category","research");failed.put("title","Percobaan gagal: "+d.filename()+" · "+x+" → "+y);failed.put("model","Pencarian model otomatis");failed.put("inputs",Map.of("datasetId",d.id(),"filename",d.filename(),"x",x,"y",y));failed.put("result",Map.of("status","ATTEMPT_FAILED","reason",Objects.toString(ex.getMessage(),"perhitungan gagal")));failed.put("sources",List.of(Map.of("datasetId",d.id(),"filename",d.filename(),"source",d.source(),"doi",d.doi())));failed.put("equations",List.of());failed.put("status","FAILED_EXPLORATORY_ATTEMPT");failed.put("limitations",List.of("Percobaan gagal tidak berarti hipotesis fisika terbukti salah."));runs.add(failed);}}if(runs.size()<250)for(String target:vars.stream().limit(4).toList()){if(runs.size()>=250)break;try{runs.add(AutonomousModelExplorer.explore(d,target));}catch(RuntimeException ex){Map<String,Object> failed=new LinkedHashMap<>();failed.put("id",UUID.randomUUID().toString());failed.put("date",java.time.Instant.now().toString());failed.put("recordType","AUTONOMOUS_MODEL_ATTEMPT");failed.put("category","research");failed.put("title","Pencarian model struktur gagal: "+d.filename()+" · "+target);failed.put("model","Feature grammar search");failed.put("inputs",Map.of("datasetId",d.id(),"filename",d.filename(),"target",target));failed.put("result",Map.of("status","MODEL_SEARCH_FAILED","reason",Objects.toString(ex.getMessage(),"model search failed")));failed.put("sources",List.of(Map.of("datasetId",d.id(),"filename",d.filename(),"doi",d.doi())));failed.put("status","FAILED_MODEL_STRUCTURE_SEARCH");failed.put("limitations",List.of("Kegagalan pencarian bukan bukti model fisika salah."));runs.add(failed);}}
  }
  for(Map<String,Object> r:runs)if("DETERMINISTIC_RESEARCH_RUN".equals(r.get("recordType"))){String internal=Objects.toString(r.get("status"),"");r.put("internalStatus",internal);List<Map<String,Object>> external=independentValidation(r,datasets);r.put("independentValidation",external);boolean has= !external.isEmpty(),replicated=external.stream().anyMatch(v->Boolean.TRUE.equals(v.get("beatsTrainingMeanBaseline")));r.put("status",!has?"NO_INDEPENDENT_SOURCE_DATASET_AVAILABLE":replicated?"PREDICTION_REPLICATED_ON_SECOND_SOURCE_DATASET":"NOT_REPLICATED_ON_SECOND_SOURCE_DATASET");}
  for(Map<String,Object> r:runs)if("AUTONOMOUS_MODEL_EXPLORATION".equals(r.get("recordType"))){String internal=Objects.toString(r.get("status"),"");r.put("internalStatus",internal);List<Map<String,Object>> external=independentModelValidation(r,datasets);r.put("independentValidation",external);boolean has=!external.isEmpty(),replicated=external.stream().anyMatch(v->Boolean.TRUE.equals(v.get("beatsTrainingMeanBaseline")));r.put("status",!has?"NO_INDEPENDENT_SOURCE_DATASET_AVAILABLE":replicated?"MODEL_PREDICTION_REPLICATED_ON_SECOND_SOURCE_DATASET":"MODEL_NOT_REPLICATED_ON_SECOND_SOURCE_DATASET");}
  Map<String,Object> summary=new LinkedHashMap<>();summary.put("id",UUID.randomUUID().toString());summary.put("date",java.time.Instant.now().toString());summary.put("recordType","DETERMINISTIC_RESEARCH_SCAN");summary.put("category","research");summary.put("title","Ringkasan pencarian otomatis dataset lokal");summary.put("model","Pemindaian model deterministik dan pemeriksaan replikasi lintas DOI");summary.put("inputs",Map.of("datasetsScanned",datasets.size(),"attempts",runs.size(),"datasetsSkippedForTooFewRows",skipped,"attemptLimit",250));summary.put("result",Map.of("status",runs.isEmpty()?"NO_ELIGIBLE_RESEARCH_PAIRS":"SCAN_COMPLETED","internallySupported",runs.stream().filter(r->"PATTERN_SUPPORTED_WITHIN_DATASET".equals(r.get("internalStatus"))||"UNVERIFIED_DATA_DERIVED_MODEL_CANDIDATE".equals(r.get("internalStatus"))).count(),"externallyReplicated",runs.stream().filter(r->("PREDICTION_REPLICATED_ON_SECOND_SOURCE_DATASET".equals(r.get("status"))||"MODEL_PREDICTION_REPLICATED_ON_SECOND_SOURCE_DATASET".equals(r.get("status")))).count(),"notReplicated",runs.stream().filter(r->("NOT_REPLICATED_ON_SECOND_SOURCE_DATASET".equals(r.get("status"))||"MODEL_NOT_REPLICATED_ON_SECOND_SOURCE_DATASET".equals(r.get("status")))).count(),"withoutIndependentDataset",runs.stream().filter(r->"NO_INDEPENDENT_SOURCE_DATASET_AVAILABLE".equals(r.get("status"))).count(),"failedRuns",runs.stream().filter(r->"FAILED_EXPLORATORY_ATTEMPT".equals(r.get("status"))).count()));summary.put("sources",List.of());summary.put("equations",List.of());summary.put("status",runs.isEmpty()?"NO_ELIGIBLE_DATA":"AUTOMATED_LOCAL_SCAN_COMPLETE");summary.put("limitations",List.of("Replikasi mensyaratkan kolom/satuan cocok dan DOI berbeda; DOI berbeda belum menjamin mutu atau independensi eksperimental.","Pola yang terulang masih kandidat model empiris, bukan hukum fisika baru.","Batas 250 percobaan per pemindaian menjaga beban komputasi."));runs.add(summary);return List.copyOf(runs);
 }
 private static String sourceIdentity(DataRepository.Dataset d){
  if(!d.doi().isBlank())return "doi:"+d.doi().trim().toLowerCase(Locale.ROOT);
  var matcher=java.util.regex.Pattern.compile("https?://ntrs\\.nasa\\.gov/citations/(\\d+)").matcher(d.source());
  return matcher.find()?"ntrs:"+matcher.group(1):"";
 }
 private static List<Map<String,Object>> independentValidation(Map<String,Object> run,List<DataRepository.Dataset> datasets){Map<String,Object> input=Json.map(run.get("inputs"));String sourceId=Objects.toString(input.get("datasetId"),""),xName=Objects.toString(input.get("x"),""),yName=Objects.toString(input.get("y"),"");DataRepository.Dataset train=datasets.stream().filter(d->d.id().equals(sourceId)).findFirst().orElse(null);if(train==null)return List.of();String trainSource=sourceIdentity(train);if(trainSource.isBlank())return List.of();double[] tx,ty;try{tx=column(train,xName);ty=column(train,yName);}catch(Exception e){return List.of();}Map<String,String> trainUnits=unitTokens(train.units());String dx=trainUnits.get(xName),dy=trainUnits.get(yName);if(dx==null||dy==null)return List.of();double mean=Arrays.stream(ty).average().orElse(0);Object rawModels=Json.map(run.get("result")).get("models");if(!(rawModels instanceof List<?> models))return List.of();List<Map<String,Object>> out=new ArrayList<>();for(var d:datasets){String externalSource=sourceIdentity(d);if(d.id().equals(sourceId)||d.rows()<3||externalSource.isBlank()||externalSource.equals(trainSource))continue;Map<String,String> units=unitTokens(d.units());if(!sameUnit(dx,units.get(xName))||!sameUnit(dy,units.get(yName)))continue;double[] vx,vy;try{vx=column(d,xName);vy=column(d,yName);}catch(Exception ex){continue;}double baseline=0;for(double v:vy)baseline+=sq(v-mean);baseline=Math.sqrt(baseline/vy.length);List<Map<String,Object>> modelScores=new ArrayList<>();for(Object mo:models){Map<String,Object> m=Json.map(mo);String alg=Objects.toString(m.get("algorithm"),"");List<?> pp=(List<?>)m.get("parameters");double[] p=new double[pp.size()];for(int i=0;i<p.length;i++)p[i]=((Number)pp.get(i)).doubleValue();double sse=0;boolean valid=true;for(int i=0;i<vx.length;i++){double pred=Discovery.predict(alg,p,vx[i]);if(!Double.isFinite(pred)){valid=false;break;}sse+=sq(vy[i]-pred);}if(!valid)continue;double rmse=Math.sqrt(sse/vx.length);Map<String,Object> score=new LinkedHashMap<>();score.put("algorithm",alg);score.put("equation",m.get("equation"));score.put("externalRmse",rmse);score.put("trainingMeanBaselineRmse",baseline);score.put("beatsTrainingMeanBaseline",rmse<baseline);modelScores.add(score);}boolean pass=modelScores.stream().anyMatch(m->Boolean.TRUE.equals(m.get("beatsTrainingMeanBaseline")));Map<String,Object> test=new LinkedHashMap<>();test.put("datasetId",d.id());test.put("filename",d.filename());test.put("doi",d.doi());test.put("source",d.source());test.put("sourceIdentifier",externalSource);test.put("trainingSourceIdentifier",trainSource);test.put("rows",Math.min(vx.length,vy.length));test.put("status",pass?"PREDICTION_BEATS_BASELINE_ON_SECOND_RECORD":"NO_CANDIDATE_BEATS_BASELINE");test.put("validationType","CROSS_SOURCE_PREDICTIVE_SCREEN — NOT STRICT REPLICATION");test.put("trainingConditions",train.conditions());test.put("externalConditions",d.conditions());test.put("models",modelScores);test.put("evidenceLimit","Distinct DOI or NASA NTRS record is a source-distinct screening criterion; it does not prove laboratory independence or matched engine configuration and test conditions.");out.add(test);if(out.size()>=5)break;}return List.copyOf(out);}
 private static List<Map<String,Object>> independentModelValidation(Map<String,Object> run,List<DataRepository.Dataset> datasets){Map<String,Object> input=Json.map(run.get("inputs"));String id=Objects.toString(input.get("datasetId"),""),target=Objects.toString(input.get("target"),"");List<String> predictors=strings(input.get("predictorsSearched"));Map<String,Object> normalization=Json.map(input.get("normalization"));DataRepository.Dataset train=datasets.stream().filter(d->d.id().equals(id)).findFirst().orElse(null);if(train==null||sourceIdentity(train).isBlank())return List.of();double[] y;try{y=column(train,target);}catch(Exception e){return List.of();}double mean=Arrays.stream(y).average().orElse(0);Map<String,String> tu=unitTokens(train.units());if(tu.get(target)==null||predictors.stream().anyMatch(p->tu.get(p)==null))return List.of();Object mo=Json.map(run.get("result")).get("bestModels");if(!(mo instanceof List<?> models))return List.of();List<Map<String,Object>> out=new ArrayList<>();for(var d:datasets){String externalSource=sourceIdentity(d);if(d.id().equals(id)||d.rows()<3||externalSource.isBlank()||externalSource.equals(sourceIdentity(train)))continue;Map<String,String> du=unitTokens(d.units());boolean unitsMatch=Objects.equals(tu.get(target),du.get(target));for(String p:predictors)unitsMatch&=sameUnit(tu.get(p),du.get(p));if(!unitsMatch)continue;double[] vy;Map<String,double[]> xv=new HashMap<>();try{vy=column(d,target);for(String p:predictors)xv.put(p,column(d,p));}catch(Exception e){continue;}double baseline=0;for(double v:vy)baseline+=sq(v-mean);baseline=Math.sqrt(baseline/vy.length);List<Map<String,Object>> scores=new ArrayList<>();for(Object object:models){Map<String,Object> model=Json.map(object);List<?> defs=(List<?>)model.get("termDefinitions"),coef=(List<?>)model.get("coefficients");double sse=0;boolean valid=true;for(int i=0;i<vy.length;i++){double pred=((Number)coef.get(0)).doubleValue();for(int k=0;k<defs.size();k++){Map<String,Object> def=Json.map(defs.get(k));List<String> cols=strings(def.get("columns"));List<?> norm=(List<?>)normalization.get(cols.get(0));double z1=(xv.get(cols.get(0))[i]-((Number)norm.get(0)).doubleValue())/((Number)norm.get(1)).doubleValue();double term=switch(Objects.toString(def.get("kind"),"")){case "linear"->z1;case "square"->z1*z1;case "exponential"->Math.exp(Math.max(-5,Math.min(5,z1)));case "log_abs"->Math.log1p(Math.abs(z1));case "interaction"->{List<?> n2=(List<?>)normalization.get(cols.get(1));double z2=(xv.get(cols.get(1))[i]-((Number)n2.get(0)).doubleValue())/((Number)n2.get(1)).doubleValue();yield z1*z2;}default->Double.NaN;};if(!Double.isFinite(term)){valid=false;break;}pred+=((Number)coef.get(k+1)).doubleValue()*term;}if(!valid||!Double.isFinite(pred)){valid=false;break;}sse+=sq(vy[i]-pred);}if(valid){double rmse=Math.sqrt(sse/vy.length);scores.add(Map.of("equation",model.get("equation"),"externalRmse",rmse,"trainingMeanBaselineRmse",baseline,"beatsTrainingMeanBaseline",rmse<baseline));}}boolean pass=scores.stream().anyMatch(m->Boolean.TRUE.equals(m.get("beatsTrainingMeanBaseline")));Map<String,Object> test=new LinkedHashMap<>();test.put("datasetId",d.id());test.put("filename",d.filename());test.put("doi",d.doi());test.put("source",d.source());test.put("sourceIdentifier",externalSource);test.put("trainingSourceIdentifier",sourceIdentity(train));test.put("status",pass?"PREDICTION_BEATS_BASELINE_ON_SECOND_RECORD":"NO_MODEL_BEATS_BASELINE");test.put("validationType","CROSS_SOURCE_MODEL_SCREEN — NOT STRICT REPLICATION");test.put("trainingConditions",train.conditions());test.put("externalConditions",d.conditions());test.put("models",scores);test.put("evidenceLimit","Distinct DOI or NASA NTRS record does not by itself establish laboratory independence or matched engine configuration and conditions.");out.add(test);if(out.size()>=5)break;}return List.copyOf(out);}
 private static double[] column(DataRepository.Dataset d,String name){List<String> h;List<List<String>> rows;if(d.format().equals("csv")){List<List<String>> t=DataRepository.csv(d.raw());h=t.get(0);rows=t.subList(1,t.size());}else{Map<String,Object> o=Json.map(Json.parse(d.raw()));h=strings(o.get("variables"));rows=new ArrayList<>();for(Object r:(List<?>)o.get("rows"))rows.add(strings(r));}int k=h.indexOf(name);if(k<0)throw new IllegalArgumentException("column absent");double[] out=new double[rows.size()];for(int i=0;i<out.length;i++){out[i]=Double.parseDouble(rows.get(i).get(k));if(!Double.isFinite(out[i]))throw new IllegalArgumentException("nonfinite observation");}return out;}
 private static Map<String,String> unitTokens(String units){Map<String,String> out=new HashMap<>();for(String pair:units.split(",")){String[] a=pair.trim().split(":",2);if(a.length==2)out.put(a[0].trim(),a[1].trim());}return out;}
 private static boolean sameUnit(String a,String b){if(a==null||b==null)return false;try{return Dimensions.parse(a).same(Dimensions.parse(b));}catch(Exception e){return a.equals(b);}}
 private static double predict(Discovery.Candidate c,double x){return Discovery.predict(c.algorithm(),c.parameters(),x);}private static double sq(double x){return x*x;}private static String join(double[]a){StringJoiner j=new StringJoiner(",");for(double v:a)j.add(Double.toString(v));return j.toString();}private static String join(List<Double>a){StringJoiner j=new StringJoiner(",");for(double v:a)j.add(Double.toString(v));return j.toString();}
 private static List<String> strings(Object o){List<String>a=new ArrayList<>();for(Object v:(List<?>)o)a.add(String.valueOf(v));return a;}
 private static List<List<String>> csv(String s){List<List<String>>out=new ArrayList<>();for(String line:s.split("\\R")){List<String>row=new ArrayList<>();StringBuilder b=new StringBuilder();boolean q=false;for(int i=0;i<line.length();i++){char c=line.charAt(i);if(c=='"'){if(q&&i+1<line.length()&&line.charAt(i+1)=='"'){b.append('"');i++;}else q=!q;}else if(c==','&&!q){row.add(b.toString());b.setLength(0);}else b.append(c);}row.add(b.toString());out.add(row);}return out;}
}
